public abstract class DataMiner {
    // Template method: the skeleton. Final on purpose.
    public final void mine(String path) {
        openFile(path);
        try {
            String raw = extractData();
            String analysis = analyzeData(raw);
            if (shouldSendReport()) {
                sendReport(analysis);
            }
        } finally {
            closeFile();
        }
    }

    protected abstract void openFile(String path);
    protected abstract String extractData();

    // Concrete default: shared, overridable only with reason.
    protected String analyzeData(String raw) {
        return raw.trim().toUpperCase();
    }

    protected void sendReport(String analysis) {
        System.out.println("REPORT: " + analysis);
    }

    // Hook: empty default, subclass opts in.
    protected boolean shouldSendReport() {
        return true;
    }

    protected void closeFile() {
        System.out.println("closing handle");
    }
}

public final class PdfMiner extends DataMiner {
    private String handle;
    @Override protected void openFile(String path) {
        handle = "pdf:" + path;
    }
    @Override protected String extractData() {
        return "rows from " + handle;
    }
}

public final class CsvMiner extends DataMiner {
    private String handle;
    @Override protected void openFile(String path) {
        handle = "csv:" + path;
    }
    @Override protected String extractData() {
        return "cells from " + handle;
    }
    @Override protected boolean shouldSendReport() {
        return false; // bulk ingest, no per-file report
    }
}
